package com.dukankhata.inventory;
import com.dukankhata.common.exception.*; import com.dukankhata.common.security.CurrentUserService; import com.dukankhata.inventory.dto.*; import com.dukankhata.product.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service public class InventoryService {
 private final ProductRepository products; private final StockMovementRepository movements; private final CurrentUserService current; private final ProductCacheService cache;
 public InventoryService(ProductRepository products,StockMovementRepository movements,CurrentUserService current,ProductCacheService cache){this.products=products;this.movements=movements;this.current=current;this.cache=cache;}
 @Transactional public StockResponse receive(UUID id,StockReceiptRequest r){Product p=locked(id); BigDecimal q=money(r.quantity()); p.setCurrentStock(p.getCurrentStock().add(q)); products.save(p); record(p,StockMovementType.PURCHASE,q,r.note()); cache.evict(current.shopId()); return StockResponse.from(p);}
 @Transactional public StockResponse adjust(UUID id,StockAdjustmentRequest r){Product p=locked(id); BigDecimal q=money(r.quantity()); if(r.direction()==StockAdjustmentRequest.AdjustmentDirection.OUT && p.getCurrentStock().compareTo(q)<0) throw new BusinessException("Insufficient stock for this adjustment"); BigDecimal delta=r.direction()==StockAdjustmentRequest.AdjustmentDirection.IN?q:q.negate(); p.setCurrentStock(p.getCurrentStock().add(delta)); products.save(p); record(p,r.direction()==StockAdjustmentRequest.AdjustmentDirection.IN?StockMovementType.ADJUSTMENT_IN:StockMovementType.ADJUSTMENT_OUT,delta,r.note()); cache.evict(current.shopId()); return StockResponse.from(p);}
 @Transactional(readOnly=true) public List<StockResponse> lowStock(){return products.findAllByShopIdAndActiveTrueOrderByNameAsc(current.shopId()).stream().filter(p->p.getCurrentStock().compareTo(p.getReorderLevel())<=0).map(StockResponse::from).toList();}
 @Transactional(readOnly=true) public List<StockMovementResponse> history(UUID id){lockedRead(id); return movements.findTop100ByShopIdAndProductIdOrderByCreatedAtDesc(current.shopId(),id).stream().map(StockMovementResponse::from).toList();}
 @Transactional public void receivePurchase(Product p,BigDecimal quantity,BigDecimal unitCost,String reference){Product locked=locked(p.getId()); BigDecimal q=money(quantity); BigDecimal cost=unitCost.setScale(2,RoundingMode.HALF_UP); BigDecimal oldQty=locked.getCurrentStock(); BigDecimal oldCost=locked.getAverageCostPrice(); BigDecimal newQty=oldQty.add(q); BigDecimal weighted=oldQty.signum()==0?cost:oldCost.multiply(oldQty).add(cost.multiply(q)).divide(newQty,2,RoundingMode.HALF_UP); locked.setCurrentStock(newQty); locked.setAverageCostPrice(weighted); products.save(locked); record(locked,StockMovementType.PURCHASE,q,reference); cache.evict(current.shopId());}
 @Transactional public void restoreForReturn(Product p,BigDecimal quantity,String invoice){Product locked=locked(p.getId()); BigDecimal q=money(quantity); locked.setCurrentStock(locked.getCurrentStock().add(q)); products.save(locked); record(locked,StockMovementType.RETURN_IN,q,"Return "+invoice); cache.evict(current.shopId());}
 @Transactional public void deductForSale(Product p,BigDecimal quantity,String invoice){Product locked=locked(p.getId()); BigDecimal q=money(quantity); if(locked.getCurrentStock().compareTo(q)<0) throw new BusinessException("Insufficient stock for "+locked.getName()+". Available: "+locked.getCurrentStock()); locked.setCurrentStock(locked.getCurrentStock().subtract(q)); products.save(locked); record(locked,StockMovementType.SALE,q.negate(),"POS "+invoice); cache.evict(current.shopId());}
 private Product locked(UUID id){return products.findByIdAndShopIdForUpdate(id,current.shopId()).orElseThrow(()->new ResourceNotFoundException("Product not found"));}
 private void lockedRead(UUID id){products.findByIdAndShopId(id,current.shopId()).orElseThrow(()->new ResourceNotFoundException("Product not found"));}
 private void record(Product p,StockMovementType type,BigDecimal q,String note){StockMovement m=new StockMovement();m.setShop(p.getShop());m.setProduct(p);m.setType(type);m.setQuantity(q.setScale(3,RoundingMode.HALF_UP));m.setBalanceAfter(p.getCurrentStock().setScale(3,RoundingMode.HALF_UP));m.setNote(note==null?null:note.trim());movements.save(m);}
 private BigDecimal money(BigDecimal q){if(q==null||q.signum()<=0)throw new BusinessException("Quantity must be greater than zero");return q.setScale(3,RoundingMode.HALF_UP);}
}
